#define NOMINMAX
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include "rr.h"
#include "rr_guides_cs.h" // generated by build.bat (dxc -Fh), defines g_rr_guides_cs

#include <atomic>
#include <cmath>
#include <mutex>

void logf(const char *fmt, ...);

namespace rr
{
	static SlFunctions s_sl;
	static std::atomic<bool> s_enabled{false};
	static ID3D12Device *s_device = nullptr;

	static std::mutex s_mtx;
	static ID3D12Resource *s_rt[8] = {};
	static sl::Constants s_constants;
	static bool s_have_constants = false;
	static sl::DLSSOptions s_dlss;
	static bool s_have_dlss = false;

	// GPU objects
	static ID3D12RootSignature *s_rootsig = nullptr;
	static ID3D12PipelineState *s_pso = nullptr;
	static ID3D12DescriptorHeap *s_heap = nullptr;
	static UINT s_inc = 0;
	static constexpr UINT k_desc_per_frame = 8; // 5 SRV + 3 UAV
	static constexpr UINT k_frames = 4;
	static UINT s_frame = 0;
	static bool s_init_failed = false;

	// Guide buffers (render resolution)
	struct Guide { ID3D12Resource *res = nullptr; DXGI_FORMAT fmt; D3D12_RESOURCE_STATES state = D3D12_RESOURCE_STATE_UNORDERED_ACCESS; };
	static Guide s_diffuse{ nullptr, DXGI_FORMAT_R8G8B8A8_UNORM }, s_specular{ nullptr, DXGI_FORMAT_R8G8B8A8_UNORM }, s_normal{ nullptr, DXGI_FORMAT_R16G16B16A16_FLOAT };
	static UINT s_guide_w = 0, s_guide_h = 0;

	static PFun_slDLSSDSetOptions *s_set_options = nullptr;
	static bool s_failed_eval_logged = false;

	void set_sl(const SlFunctions &fns) { s_sl = fns; }
	// The addon now stays loaded across devices (ReShade LoadFromDllMain); FH6 creates and destroys a probe
	// device first. Always follow the newest device and forget objects that belonged to an older one.
	void on_device(ID3D12Device *device)
	{
		if (!device || device == s_device) return;
		std::lock_guard lock(s_mtx);
		s_device = device;
		s_rootsig = nullptr; s_pso = nullptr; s_heap = nullptr; s_init_failed = false;
		s_diffuse.res = s_specular.res = s_normal.res = nullptr; s_guide_w = s_guide_h = 0;
		for (auto &r : s_rt) r = nullptr;
		logf("RR: using device %p", device);
	}
	void on_gbuffer(ID3D12Resource *const rts[8]) { std::lock_guard lock(s_mtx); for (int i = 0; i < 8; ++i) s_rt[i] = rts[i]; }
	void on_constants(const sl::Constants &c) { std::lock_guard lock(s_mtx); s_constants = c; s_have_constants = true; }
	void on_dlss_options(const sl::DLSSOptions &o) { std::lock_guard lock(s_mtx); s_dlss = o; s_have_dlss = true; }
	bool enabled() { return s_enabled.load(); }
	void set_enabled(bool on) { s_enabled = on; }

	void toggle()
	{
		const bool on = !s_enabled.load();
		s_enabled = on;
		bool loaded = false;
		if (s_sl.is_feature_loaded) s_sl.is_feature_loaded(sl::kFeatureDLSS_RR, loaded);
		logf("RR: %s (dlss_d plugin loaded=%d)", on ? "ON" : "OFF", (int)loaded);
	}

	static bool init_gpu()
	{
		if (s_pso) return true;
		if (s_init_failed || !s_device) return false;
		s_init_failed = true;

		using PFN_Serialize = HRESULT(WINAPI *)(const D3D12_ROOT_SIGNATURE_DESC *, D3D_ROOT_SIGNATURE_VERSION, ID3DBlob **, ID3DBlob **);
		auto serialize = reinterpret_cast<PFN_Serialize>(GetProcAddress(GetModuleHandleW(L"d3d12.dll"), "D3D12SerializeRootSignature"));
		if (!serialize) return false;

		D3D12_DESCRIPTOR_RANGE ranges[2] = {};
		ranges[0] = { D3D12_DESCRIPTOR_RANGE_TYPE_SRV, 5, 0, 0, 0 };
		ranges[1] = { D3D12_DESCRIPTOR_RANGE_TYPE_UAV, 3, 0, 0, 0 };
		D3D12_ROOT_PARAMETER params[3] = {};
		params[0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
		params[0].Constants = { 0, 0, 16 };
		params[1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
		params[1].DescriptorTable = { 1, &ranges[0] };
		params[2].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
		params[2].DescriptorTable = { 1, &ranges[1] };
		const D3D12_ROOT_SIGNATURE_DESC rsd = { 3, params, 0, nullptr, D3D12_ROOT_SIGNATURE_FLAG_NONE };
		ID3DBlob *blob = nullptr, *err = nullptr;
		if (FAILED(serialize(&rsd, D3D_ROOT_SIGNATURE_VERSION_1, &blob, &err))) { if (err) err->Release(); logf("RR: root signature serialize failed"); return false; }
		HRESULT hr = s_device->CreateRootSignature(0, blob->GetBufferPointer(), blob->GetBufferSize(), IID_PPV_ARGS(&s_rootsig));
		blob->Release();
		if (FAILED(hr)) { logf("RR: CreateRootSignature failed 0x%08lx", hr); return false; }

		D3D12_COMPUTE_PIPELINE_STATE_DESC pd = {};
		pd.pRootSignature = s_rootsig;
		pd.CS = { g_rr_guides_cs, sizeof(g_rr_guides_cs) };
		hr = s_device->CreateComputePipelineState(&pd, IID_PPV_ARGS(&s_pso));
		if (FAILED(hr)) { logf("RR: CreateComputePipelineState failed 0x%08lx", hr); return false; }

		const D3D12_DESCRIPTOR_HEAP_DESC hd = { D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV, k_desc_per_frame * k_frames, D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE, 0 };
		hr = s_device->CreateDescriptorHeap(&hd, IID_PPV_ARGS(&s_heap));
		if (FAILED(hr)) { logf("RR: CreateDescriptorHeap failed 0x%08lx", hr); s_pso->Release(); s_pso = nullptr; return false; }
		s_inc = s_device->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
		s_init_failed = false;
		logf("RR: guide pass initialized");
		return true;
	}

	static bool ensure_guides(UINT w, UINT h)
	{
		if (s_guide_w == w && s_guide_h == h && s_diffuse.res) return true;
		for (Guide *g : { &s_diffuse, &s_specular, &s_normal })
		{
			if (g->res) { g->res->Release(); g->res = nullptr; }
			D3D12_HEAP_PROPERTIES hp = { D3D12_HEAP_TYPE_DEFAULT };
			D3D12_RESOURCE_DESC rd = {};
			rd.Dimension = D3D12_RESOURCE_DIMENSION_TEXTURE2D;
			rd.Width = w; rd.Height = h; rd.DepthOrArraySize = 1; rd.MipLevels = 1;
			rd.Format = g->fmt; rd.SampleDesc.Count = 1;
			rd.Flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;
			if (FAILED(s_device->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &rd, D3D12_RESOURCE_STATE_UNORDERED_ACCESS, nullptr, IID_PPV_ARGS(&g->res))))
			{
				logf("RR: failed to create %ux%u guide buffer", w, h);
				return false;
			}
			g->state = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
		}
		s_diffuse.res->SetName(L"fh6rr.guide.diffuse_albedo");
		s_specular.res->SetName(L"fh6rr.guide.specular_albedo");
		s_normal.res->SetName(L"fh6rr.guide.normal_roughness");
		s_guide_w = w; s_guide_h = h;
		logf("RR: guide buffers %ux%u", w, h);
		return true;
	}

	static void transition(ID3D12GraphicsCommandList *cmd, Guide &g, D3D12_RESOURCE_STATES to)
	{
		if (g.state == to) return;
		D3D12_RESOURCE_BARRIER b = {};
		b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
		b.Transition.pResource = g.res;
		b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
		b.Transition.StateBefore = g.state;
		b.Transition.StateAfter = to;
		cmd->ResourceBarrier(1, &b);
		g.state = to;
	}

	static void write_srv(D3D12_CPU_DESCRIPTOR_HANDLE h, ID3D12Resource *res, DXGI_FORMAT fmt)
	{
		D3D12_SHADER_RESOURCE_VIEW_DESC d = {};
		d.Format = fmt;
		d.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
		d.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
		d.Texture2D.MipLevels = 1;
		s_device->CreateShaderResourceView(res, &d, h);
	}

	static void write_uav(D3D12_CPU_DESCRIPTOR_HANDLE h, ID3D12Resource *res, DXGI_FORMAT fmt)
	{
		D3D12_UNORDERED_ACCESS_VIEW_DESC d = {};
		d.Format = fmt;
		d.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
		s_device->CreateUnorderedAccessView(res, nullptr, &d, h);
	}

	static void record_guides(ID3D12GraphicsCommandList *cmd, ID3D12Resource *const rt[8], const sl::Constants &c, UINT w, UINT h)
	{
		const UINT base = (s_frame++ % k_frames) * k_desc_per_frame;
		D3D12_CPU_DESCRIPTOR_HANDLE cpu = s_heap->GetCPUDescriptorHandleForHeapStart();
		D3D12_GPU_DESCRIPTOR_HANDLE gpu = s_heap->GetGPUDescriptorHandleForHeapStart();
		cpu.ptr += SIZE_T(base) * s_inc; gpu.ptr += UINT64(base) * s_inc;
		auto at = [&](UINT i) { D3D12_CPU_DESCRIPTOR_HANDLE x = cpu; x.ptr += SIZE_T(i) * s_inc; return x; };

		write_srv(at(0), rt[3], DXGI_FORMAT_R32_UINT);
		write_srv(at(1), rt[4], DXGI_FORMAT_R8G8B8A8_UNORM_SRGB);
		write_srv(at(2), rt[6], DXGI_FORMAT_R32_UINT);
		write_srv(at(3), rt[7], DXGI_FORMAT_R32_UINT);
		write_srv(at(4), rt[2], DXGI_FORMAT_R8G8B8A8_UINT);
		write_uav(at(5), s_diffuse.res, s_diffuse.fmt);
		write_uav(at(6), s_specular.res, s_specular.fmt);
		write_uav(at(7), s_normal.res, s_normal.fmt);

		transition(cmd, s_diffuse, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
		transition(cmd, s_specular, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
		transition(cmd, s_normal, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

		ID3D12DescriptorHeap *heaps[] = { s_heap };
		cmd->SetDescriptorHeaps(1, heaps);
		cmd->SetComputeRootSignature(s_rootsig);
		cmd->SetPipelineState(s_pso);

		float k[16] = {};
		reinterpret_cast<UINT *>(k)[0] = w;
		reinterpret_cast<UINT *>(k)[1] = h;
		k[2] = c.cameraViewToClip[0].x != 0.0f ? 1.0f / c.cameraViewToClip[0].x : 1.0f;
		k[3] = c.cameraViewToClip[1].y != 0.0f ? 1.0f / c.cameraViewToClip[1].y : 1.0f;
		k[4] = c.cameraRight.x; k[5] = c.cameraRight.y; k[6] = c.cameraRight.z;
		k[8] = c.cameraUp.x; k[9] = c.cameraUp.y; k[10] = c.cameraUp.z;
		k[12] = c.cameraFwd.x; k[13] = c.cameraFwd.y; k[14] = c.cameraFwd.z;
		cmd->SetComputeRoot32BitConstants(0, 16, k, 0);
		D3D12_GPU_DESCRIPTOR_HANDLE srv = gpu, uav = gpu; uav.ptr += UINT64(5) * s_inc;
		cmd->SetComputeRootDescriptorTable(1, srv);
		cmd->SetComputeRootDescriptorTable(2, uav);
		cmd->Dispatch((w + 7) / 8, (h + 7) / 8, 1);

		transition(cmd, s_diffuse, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
		transition(cmd, s_specular, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
		transition(cmd, s_normal, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
	}

	// Streamline matrices are row-major for row vectors (p * M), see cameraViewToClip in captures.
	static void build_view_matrices(const sl::Constants &c, sl::float4x4 &world_to_view, sl::float4x4 &view_to_world)
	{
		const sl::float3 r = c.cameraRight, u = c.cameraUp, f = c.cameraFwd, p = c.cameraPos;
		world_to_view[0] = { r.x, u.x, f.x, 0.0f };
		world_to_view[1] = { r.y, u.y, f.y, 0.0f };
		world_to_view[2] = { r.z, u.z, f.z, 0.0f };
		world_to_view[3] = { -(p.x * r.x + p.y * r.y + p.z * r.z), -(p.x * u.x + p.y * u.y + p.z * u.z), -(p.x * f.x + p.y * f.y + p.z * f.z), 1.0f };
		view_to_world[0] = { r.x, r.y, r.z, 0.0f };
		view_to_world[1] = { u.x, u.y, u.z, 0.0f };
		view_to_world[2] = { f.x, f.y, f.z, 0.0f };
		view_to_world[3] = { p.x, p.y, p.z, 1.0f };
	}

	static volatile int s_step = 0;      // last step reached (for crash reports)
	static bool s_trace = true;          // log each step on the first evaluate
#define RR_STEP(n, what) do { s_step = (n); if (s_trace) logf("RR step %d: %s", (n), (what)); } while (0)

	static bool evaluate_impl(const sl::FrameToken &frame, const sl::BaseStructure **inputs, uint32_t num_inputs, sl::CommandBuffer *cmd, ID3D12GraphicsCommandList *native)
	{
		RR_STEP(1, "enter");
		if (!native || !s_sl.evaluate || !s_sl.set_tag_for_frame || !s_sl.get_feature_function) return false;

		ID3D12Resource *rt[8]; sl::Constants c; sl::DLSSOptions dlss; bool have_c, have_d;
		{
			std::lock_guard lock(s_mtx);
			memcpy(rt, s_rt, sizeof(rt)); c = s_constants; dlss = s_dlss; have_c = s_have_constants; have_d = s_have_dlss;
		}
		if (!have_c || !have_d || !rt[3] || !rt[4] || !rt[2]) return false;

		// Viewport handle passed by the game to the DLSS evaluate
		const sl::ViewportHandle *vp = nullptr;
		for (uint32_t i = 0; i < num_inputs && !vp; ++i)
			for (const sl::BaseStructure *b = inputs[i]; b; b = b->next)
				if (b->structType == sl::ViewportHandle::s_structType) { vp = static_cast<const sl::ViewportHandle *>(b); break; }
		if (!vp) return false;

		RR_STEP(2, "get slDLSSDSetOptions");
		if (!s_set_options)
		{
			void *fn = nullptr;
			const sl::Result r = s_sl.get_feature_function(sl::kFeatureDLSS_RR, "slDLSSDSetOptions", fn);
			if (r != sl::Result::eOk || !fn)
			{
				if (!s_failed_eval_logged) { s_failed_eval_logged = true; logf("RR: slDLSSDSetOptions unavailable (%d) - is the dlss_d plugin loaded? Falling back to DLSS.", (int)r); }
				return false;
			}
			s_set_options = reinterpret_cast<PFun_slDLSSDSetOptions *>(fn);
		}

		RR_STEP(3, "init guide pass");
		if (!init_gpu()) return false;
		const D3D12_RESOURCE_DESC src = rt[3]->GetDesc();
		const UINT w = (UINT)src.Width, h = src.Height;
		RR_STEP(4, "create guide buffers");
		if (!ensure_guides(w, h)) return false;

		RR_STEP(5, "record guide pass");
		record_guides(native, rt, c, w, h);

		// Options: mirror the game's DLSS mode/output, add RR specifics
		sl::DLSSDOptions o;
		o.mode = dlss.mode;
		o.outputWidth = dlss.outputWidth;
		o.outputHeight = dlss.outputHeight;
		o.preExposure = dlss.preExposure;
		o.exposureScale = dlss.exposureScale;
		o.colorBuffersHDR = dlss.colorBuffersHDR;
		o.normalRoughnessMode = sl::DLSSDNormalRoughnessMode::ePacked;
		build_view_matrices(c, o.worldToCameraView, o.cameraViewToWorld);
		RR_STEP(6, "slDLSSDSetOptions");
		sl::Result r = s_set_options(*vp, o);
		if (r != sl::Result::eOk)
		{
			if (!s_failed_eval_logged) { s_failed_eval_logged = true; logf("RR: slDLSSDSetOptions failed (%d), falling back to DLSS", (int)r); }
			return false;
		}

		// Tag our guide buffers for this frame (color/depth/mvec/output were already tagged by the game)
		sl::Extent ext{}; ext.width = w; ext.height = h;
		sl::Resource rd(sl::ResourceType::eTex2d, s_diffuse.res, (uint32_t)s_diffuse.state);
		sl::Resource rs(sl::ResourceType::eTex2d, s_specular.res, (uint32_t)s_specular.state);
		sl::Resource rn(sl::ResourceType::eTex2d, s_normal.res, (uint32_t)s_normal.state);
		const sl::ResourceTag tags[] = {
			sl::ResourceTag(&rd, sl::kBufferTypeAlbedo, sl::ResourceLifecycle::eValidUntilPresent, &ext),
			sl::ResourceTag(&rs, sl::kBufferTypeSpecularAlbedo, sl::ResourceLifecycle::eValidUntilPresent, &ext),
			sl::ResourceTag(&rn, sl::kBufferTypeNormalRoughness, sl::ResourceLifecycle::eValidUntilPresent, &ext),
		};
		RR_STEP(7, "tag guides");
		r = s_sl.set_tag_for_frame(frame, *vp, tags, 3, cmd);
		if (r != sl::Result::eOk)
		{
			if (!s_failed_eval_logged) { s_failed_eval_logged = true; logf("RR: tagging guides failed (%d), falling back to DLSS", (int)r); }
			return false;
		}

		RR_STEP(8, "slEvaluateFeature(DLSS_RR)");
		r = s_sl.evaluate(sl::kFeatureDLSS_RR, frame, inputs, num_inputs, cmd);
		RR_STEP(9, "evaluate returned");
		s_trace = false;
		if (r != sl::Result::eOk)
		{
			if (!s_failed_eval_logged) { s_failed_eval_logged = true; logf("RR: slEvaluateFeature(DLSS_RR) failed (%d); this frame has no upscale", (int)r); }
			return false;
		}
		static bool logged = false;
		if (!logged) { logged = true; logf("RR: first evaluate OK (%ux%u -> %ux%u)", w, h, o.outputWidth, o.outputHeight); }
		return true;
	}

	static DWORD s_fault_code = 0;
	static void *s_fault_addr = nullptr;
	static int seh_filter(EXCEPTION_POINTERS *ep)
	{
		s_fault_code = ep->ExceptionRecord->ExceptionCode;
		s_fault_addr = ep->ExceptionRecord->ExceptionAddress;
		// Only handle real faults; let the game's guard-page tricks etc. pass through untouched
		return (s_fault_code == EXCEPTION_ACCESS_VIOLATION || s_fault_code == EXCEPTION_ILLEGAL_INSTRUCTION || s_fault_code == EXCEPTION_INT_DIVIDE_BY_ZERO)
			? EXCEPTION_EXECUTE_HANDLER : EXCEPTION_CONTINUE_SEARCH;
	}

	bool evaluate(const sl::FrameToken &frame, const sl::BaseStructure **inputs, uint32_t num_inputs, sl::CommandBuffer *cmd, ID3D12GraphicsCommandList *native)
	{
		if (!s_enabled.load()) return false;
		__try
		{
			return evaluate_impl(frame, inputs, num_inputs, cmd, native);
		}
		__except (seh_filter(GetExceptionInformation()))
		{
			s_enabled = false;
			HMODULE mod = nullptr; char name[MAX_PATH] = "?";
			if (GetModuleHandleExA(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT, (LPCSTR)s_fault_addr, &mod) && mod)
				GetModuleFileNameA(mod, name, MAX_PATH);
			logf("RR: FAULT 0x%08lx at %p (%s +0x%llx) in step %d - RR disabled", s_fault_code, s_fault_addr, name,
				mod ? (unsigned long long)((char *)s_fault_addr - (char *)mod) : 0ull, (int)s_step);
			return false;
		}
	}
}